<?php

namespace Tests;

use Foundation\Argparse;
use Foundation\Argparse\ArgumentError;
use Foundation\Argparse\ArgumentParser;
use Icloudpd\Cli;
use PHPUnit\Framework\Attributes\DataProvider;

/**
 * `Foundation\Argparse` against the output of Python 3.13's argparse: `icloudpd.cli.parse` and
 * `format_help` of the Python tool (cases generated by running it), and the help of the parser of
 * `pyicloud_ipd/cmdline.py`.
 */
class FoundationArgparseTest extends TestCase
{
    private string|false $columns;

    protected function setUp(): void
    {
        parent::setUp();
        $this->columns = getenv('COLUMNS');
        // the warnings of deprecated options (--threads-num) go to Python's sys.stderr
        Argparse::$stderr = fopen('php://memory', 'w+');
    }

    protected function tearDown(): void
    {
        putenv($this->columns === false ? 'COLUMNS' : "COLUMNS={$this->columns}");
        Argparse::$stderr = null;
        parent::tearDown();
    }

