    #[DataProvider('parse_cases')]
    public function test_parse_like_python(array $args, string $status, mixed $expected): void
    {
        if ($status === 'error') {
            try {
                Cli::parse($args);
                $this->fail('ArgumentError expected');
            } catch (ArgumentError $error) {
                $this->assertSame($expected, $error->getMessage());
            }
            return;
        }

        [$global, $users] = Cli::parse($args);
        $date = fn($v) => match (true) {
            $v === null => null,
            $v instanceof \DateTimeImmutable => $v->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d\TH:i:s'),
            default => 'P' . $v->d . 'D',
        };
        $this->assertSame($expected, [
            'help' => $global->help,
            'version' => $global->version,
            'use_os_locale' => $global->use_os_locale,
            'log_level' => $global->log_level->name,
            'domain' => $global->domain,
            'threads_num' => $global->threads_num,
            'password_providers' => array_map(fn($p) => $p->name, $global->password_providers),
            'mfa' => $global->mfa_provider->name,
            'users' => array_map(fn($u) => [
                'username' => $u->username,
                'password' => $u->password,
                'directory' => $u->directory,
                'recent' => $u->recent,
                'albums' => $u->albums,
                'sizes' => array_map(fn($s) => $s->name, $u->sizes),
                'list_albums' => $u->list_albums,
                'folder_structure' => $u->folder_structure,
                'smtp_port' => $u->smtp_port,
                'align_raw' => $u->align_raw->name,
                'file_match_policy' => $u->file_match_policy->name,
                'mov' => $u->live_photo_mov_filename_policy->name,
                'notification_script' => $u->notification_script,
                'before' => $date($u->skip_created_before),
                'after' => $date($u->skip_created_after),
            ], $users),
        ]);
    }

    /** `hashlib.md5(format_help())` of the Python tool, by terminal width */
    public function test_cli_help_like_python(): void
    {
        $md5 = [
        30 => '5d6a1cf7dbd2ead5535a603030b3a3f4',
        40 => '51969128245c2e5e4be6f9c871bcd4be',
        80 => '82adb10f1242982dd1dbcd94b1168820',
        120 => '4707568b6121a84a5b8f9b2d081c2949',
        200 => '829039f454515920e8c632f41b5bc5e7',
        ];
        foreach ($md5 as $columns => $expected) {
            putenv("COLUMNS={$columns}");
            $this->assertSame($expected, md5(Cli::format_help()), "COLUMNS={$columns}");
        }
    }

    private function icloud_parser(): ArgumentParser
    {
        $parser = new ArgumentParser(prog: 'icloud', description: 'Find My iPhone CommandLine Tool');
        $parser->add_argument('--username', action: 'store', dest: 'username', default: '', help: 'Apple ID to Use');
        $parser->add_argument('--password', action: 'store', dest: 'password', default: '', help: 'Apple ID Password to Use; if unspecified, password will be fetched from the system keyring.');
        $parser->add_argument('-n', '--non-interactive', action: 'store_false', dest: 'interactive', default: true, help: 'Disable interactive prompts.');
        $parser->add_argument('--delete-from-keyring', action: 'store_true', dest: 'delete_from_keyring', default: false, help: 'Delete stored password in system keyring for this username.');
        $parser->add_argument('--domain', action: 'store', dest: 'domain', default: 'com', help: 'Root domain for requests to iCloud. com or cn');
        $parser->add_argument('--version', action: 'store_true', dest: 'version', help: 'Show the version, commit hash and timestamp');
        return $parser;
    }

    /** the help and the usage (wrapped when the terminal is narrow) of the parser of `bin/icloud` */
    public function test_help_and_usage_like_python(): void
    {
        $expected = [
        80 => [<<<'EOT'
usage: icloud [-h] [--username USERNAME] [--password PASSWORD] [-n]
              [--delete-from-keyring] [--domain DOMAIN] [--version]

Find My iPhone CommandLine Tool

options:
  -h, --help            show this help message and exit
  --username USERNAME   Apple ID to Use
  --password PASSWORD   Apple ID Password to Use; if unspecified, password
                        will be fetched from the system keyring.
  -n, --non-interactive
                        Disable interactive prompts.
  --delete-from-keyring
                        Delete stored password in system keyring for this
                        username.
  --domain DOMAIN       Root domain for requests to iCloud. com or cn
  --version             Show the version, commit hash and timestamp
EOT,
        <<<'EOT'
usage: icloud [-h] [--username USERNAME] [--password PASSWORD] [-n]
              [--delete-from-keyring] [--domain DOMAIN] [--version]
EOT],
        30 => [<<<'EOT'
usage: icloud [-h]
              [--username USERNAME]
              [--password PASSWORD]
              [-n]
              [--delete-from-keyring]
              [--domain DOMAIN]
              [--version]

Find My iPhone CommandLine
Tool

options:
  -h, --help
        show this help
        message and exit
  --username USERNAME
        Apple ID to Use
  --password PASSWORD
        Apple ID Password to
        Use; if unspecified,
        password will be
        fetched from the
        system keyring.
  -n, --non-interactive
        Disable interactive
        prompts.
  --delete-from-keyring
        Delete stored
        password in system
        keyring for this
        username.
  --domain DOMAIN
        Root domain for
        requests to iCloud.
        com or cn
  --version
        Show the version,
        commit hash and
        timestamp
EOT,
        <<<'EOT'
usage: icloud [-h]
              [--username USERNAME]
              [--password PASSWORD]
              [-n]
              [--delete-from-keyring]
              [--domain DOMAIN]
              [--version]
