    public function test_icloud_parser_values(): void
    {
        $ns = $this->icloud_parser()->parse_args(['--user=foo', '--pass', 'bar', '-n', '--delete-from-keyring']);
        $this->assertSame('foo', $ns->username);
        $this->assertSame('bar', $ns->password);
        $this->assertFalse($ns->interactive);
        $this->assertTrue($ns->delete_from_keyring);
        $this->assertSame('com', $ns->domain);
        $this->assertFalse($ns->version);

        // -n -h would exit: store_false and abbreviations only
        [$ns, $extras] = $this->icloud_parser()->parse_known_args(['--domain=a=b', '--bogus', 'x']);
        $this->assertSame('a=b', $ns->domain);
        $this->assertSame(['--bogus', 'x'], $extras);
    }

    /** `parse_args` on a parser that does not exit (exit_on_error=False) raises instead of printing */
    public function test_errors_raise_without_exit_on_error(): void
    {
        $parser = new ArgumentParser(prog: 'p', add_help: false, exit_on_error: false);
        $parser->add_argument('--n', type: 'int');
        $this->expectException(ArgumentError::class);
        $this->expectExceptionMessage("argument --n: invalid int value: 'x'");
        $parser->parse_args(['--n', 'x']);
    }

    /** `copy.deepcopy(parser)`: the copy has its own actions and groups, the original is left alone */
    public function test_clone_is_a_deep_copy(): void
    {
        $parser = new ArgumentParser(prog: 'p', add_help: false, exit_on_error: false);
        $group = $parser->add_mutually_exclusive_group();
        $group->add_argument('--a', action: 'store_true');
        $group->add_argument('--b', action: 'store_true');
        $parser->add_argument('--c', default: 'cc');

        $copy = clone $parser;
        $copy->add_argument('--d', default: 'dd');
        $copy->_actions[2]->default = 'changed';

        $this->assertCount(3, $parser->_actions);
        $this->assertCount(4, $copy->_actions);
        $this->assertSame('cc', $parser->parse_args([])->c);
        $this->assertSame('changed', $copy->parse_args([])->c);
        $this->assertSame('dd', $copy->parse_args([])->d);

        // the copied mutually exclusive group still excludes
        $this->expectException(ArgumentError::class);
        $this->expectExceptionMessage('argument --b: not allowed with argument --a');
        $copy->parse_args(['--a', '--b']);
    }

    public function test_print_usage_and_help_to_a_stream(): void
    {
        putenv('COLUMNS=80');
        $stream = fopen('php://memory', 'w+');
        $parser = $this->icloud_parser();
        $parser->print_usage($stream);
        $parser->print_help($stream);
        rewind($stream);
        $this->assertSame($parser->format_usage() . $parser->format_help(), stream_get_contents($stream));
    }
}
